#!/usr/bin/env bash
# In-repo copy for tests/doctor_runner.rs (unit U0, 2026-10-14). Source: the review package,
# local/doctor/tutorial/run-doctor-demo.sh. Changes from the source are marked U0-EDIT. Run through
# `cargo test --test doctor_runner`, or scripts/behaviour-lock.sh doctor to compare two binaries.
# evnx doctor demo runner (DR0-DR10). Non-interactive (no terminal), safe: each scene runs in its own temp folder.
# Usage: EVNX=/path/to/evnx ./run-doctor-demo.sh [DR5 ...]
# "KNOWN" lines mark behaviour logged as an issue in the review (22-doctor.md); they show 0.10.0 as it is today.
# Real git repositories are used where git decides the answer (an empty .git folder is not a repository).
# Nothing here touches the network. All values are synthetic.
set -u
EVNX="${EVNX:-evnx}"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DEMO_ROOT="${DEMO_ROOT:-$(mktemp -d)}"
export NO_COLOR=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null
unset EVNX_PASSWORD EVNX_OUTPUT_JSON EVNX_AUTO_FIX
pass=0; fail=0
run() { echo; echo "\$ ${*/#$EVNX/evnx}"; "$@" > "$DEMO_ROOT/.out" 2>"$DEMO_ROOT/.err" </dev/null; local rc=$?; cat "$DEMO_ROOT/.out"; [ -s "$DEMO_ROOT/.err" ] && { echo "[stderr]"; cat "$DEMO_ROOT/.err"; }; echo "[exit $rc]"; LAST=$rc; }
expect() { if [ "$LAST" -eq "$1" ]; then pass=$((pass+1)); echo "  ok: $2 (exit $1)"; else fail=$((fail+1)); echo "  MISMATCH: $2 expected exit $1, got $LAST"; fi; }
check() { if eval "$1"; then pass=$((pass+1)); echo "  ok: $2"; else fail=$((fail+1)); echo "  MISMATCH: $2"; fi; }
scene() { echo; echo "================ $1 ================"; D="$DEMO_ROOT/$1"; rm -rf "$D"; mkdir -p "$D"; cd "$D" || exit 1; }
repo() { git init -q . && git config user.email demo@example.com && git config user.name demo && git config commit.gpgsign false; }
commit() { git add -A >/dev/null 2>&1; git commit -q -m "$1" >/dev/null 2>&1; }
good_ignore() { printf '.env*\n!.env.example\n!.env.sample\n!.env.template\n' > .gitignore; }
healthy() { repo; printf 'DB_URL=postgres://user:pw@db.internal/app\nPORT=8080\n' > .env; chmod 600 .env; printf 'DB_URL=\nPORT=\n' > .env.example; good_ignore; commit init; }
mode() { stat -c '%a' "$1"; }

# R-doctor-EDIT (2026-10-22): DR0 flipped on purpose (D-118).
DR0() { scene DR0; healthy; run "$EVNX" --version; run "$EVNX" doctor --help; check '"$EVNX" doctor --help | grep -q "Exit codes"' "FIXED D-118 (R-doctor): --help has an 'Exit codes' section, and an Environment one"; run "$EVNX" doctor --format yaml; expect 2 "unknown format is exit 2 'No verdict'"; run "$EVNX" doctor nowhere; expect 2 "missing directory: exit 2, not a clean result"; touch afile; run "$EVNX" doctor afile; expect 2 "a file is not a directory: exit 2"; run "$EVNX" doctor . --path .; expect 2 "positional and --path conflict"; }
DR1() { scene DR1; healthy; run "$EVNX" doctor; expect 0 "healthy project, real repo: exit 0"; run "$EVNX" doctor --verbose; expect 0 "verbose shows the ticks"; run "$EVNX" doctor --format json; expect 0 "json"; check '"$EVNX" doctor --format json 2>/dev/null | python3 -c "import json,sys; d=json.load(sys.stdin); assert d[\"summary\"][\"errors\"]==0 and len(d[\"checks\"])==6"' "JSON on stdout only: 6 checks (ai_agents since RM-25), 0 errors"; check '"$EVNX" doctor 2>/dev/null | grep -c $'"'"'\033'"'"' | grep -qx 0' "no colour escapes when piped"; }
# U2-EDIT (2026-10-15): DR2 flipped on purpose: section header and Fixed: lines (I-168, I-165, DEC-D1).
DR2() { scene DR2; repo; printf 'AWS=AKIA4OZRMFJ3VREALKEY\n' > .env; chmod 644 .env; run "$EVNX" doctor; expect 1 ".env not ignored and mode 644: errors, exit 1"; run "$EVNX" doctor --fix; expect 0 "--fix repairs both and exits 0"; run cat .gitignore; echo "I-168 fixed: doctor writes the evnx section through the one .gitignore writer"; check '[ "$(mode .env)" = 600 ]' ".env is now 600"; check 'grep -q "evnx generated" .gitignore' "I-168 fixed: the section header is written"; run "$EVNX" doctor; expect 0 "healthy without --fix"; echo "I-165 fixed (DEC-D1): --fix prints one Fixed: line per change, on stderr"; }
# U2-EDIT (2026-10-15): DR3 flipped on purpose (I-156, I-157, DEC-D1, DEC-D2).
DR3() { scene DR3; healthy; echo 'KEY=1' >> .env; git add -f .env >/dev/null; git commit -q -m "oops: commit .env"; run git ls-files .env; run "$EVNX" doctor; expect 1 "I-157 fixed (DEC-D2): a committed .env is reported as tracked by git, with git rm --cached"; run "$EVNX" doctor --fix; expect 1 "I-156 fixed (DEC-D1, DEC-D2): --fix never runs git, so a tracked file is not fixed, exit 1"; run "$EVNX" doctor; expect 1 "...and the next plain run still fails: nothing was repaired"; run git ls-files .env; }
# U2-EDIT (2026-10-15): DR4 flipped on purpose (I-156, DEC-D1). commit adds .env here, so doctor reports it tracked (I-157).
DR4() { scene DR4; healthy; printf '.env*\n!.env\n' > .gitignore; commit gi; run "$EVNX" doctor; expect 1 ".env* then !.env: .env is exposed"; run "$EVNX" doctor --fix; expect 1 "I-156 fixed (DEC-D1): --fix re-checks; still exposed is not fixed, exit 1"; run cat .gitignore; run "$EVNX" doctor; expect 1 "still exposed on the next run; decided (DEC-D1): verify after fix, exit 1"; }
# R-doctor-EDIT (2026-10-22): DR5 flipped on purpose (I-173, I-160, DEC-D3, DEC-D5, DEC-D18).
DR5() { scene DR5; healthy; printf '.env\n' > .gitignore; commit gi; printf 'use flake\n' > .envrc; run "$EVNX" doctor; expect 0 "FIXED I-173 (DEC-D3): a direnv .envrc is not an env file"; printf 'hello\n' > .environment; printf 'notes\n' > .env-notes.md; run "$EVNX" doctor; expect 0 "FIXED I-173 (DEC-D3): .environment and .env-notes.md are not env files either"; rm .envrc .environment .env-notes.md; cp .env .env.bak; cp .env .env.backup; run "$EVNX" doctor; expect 1 "FIXED I-160 (DEC-D5, DEC-D18): the plaintext copy .env.bak is an error until ignored..."; check '"$EVNX" doctor 2>&1 | grep -q ".env.backup is NOT in .gitignore (security risk): a plaintext copy"' "FIXED I-160: ...and so is .env.backup, read by content: only an evnx backup (ciphertext) is skipped"; }
# R-doctor-EDIT (2026-10-22): DR6 flipped on purpose (I-158, I-170, I-159, DEC-D4, DEC-D6).
DR6() { scene DR6; healthy; printf 'P=1\n' > .env.production; chmod 644 .env.production; run "$EVNX" doctor; expect 0 "FIXED I-158 (DEC-D4): .env.production at 644 is a warning"; check '"$EVNX" doctor 2>&1 | grep -q ".env.production: permissions 644"' "FIXED I-158: the warning names the file"; chmod 700 .env; run "$EVNX" doctor; expect 0 "mode 700 on .env"; check '! "$EVNX" doctor 2>&1 | grep -q ".env: permissions 700"' "FIXED I-170 (DEC-D4): mode 700 is private (no group/other access); only .env.production is named"; chmod 644 .env; run "$EVNX" doctor --fix; check '[ "$(mode .env)" = 600 ] && [ "$(mode .env.production)" = 600 ]' "FIXED I-158 (DEC-D4): --fix sets every flagged env file to 600"; mkdir ../outside-DR6 2>/dev/null; printf 'S=1\n' > ../outside-DR6/real.env; chmod 644 ../outside-DR6/real.env; rm .env; ln -s ../outside-DR6/real.env .env; run "$EVNX" doctor; check '"$EVNX" doctor 2>&1 | grep -q "symlink to ../outside-DR6/real.env"' "FIXED I-159 (DEC-D6): the symlinked .env is seen and named as a symlink"; run "$EVNX" doctor --fix; check '[ "$(mode ../outside-DR6/real.env)" = 644 ]' "FIXED I-159 (DEC-D6): --fix leaves a target outside the project alone and prints the chmod"; }
# R-doctor-EDIT (2026-10-22): DR7 flipped on purpose (I-161, DEC-D7).
DR7() { scene DR7; healthy; printf 'GOOD=1\n!!bad one\nALSO=2\n@@bad two\n# fine\n%%%%bad three\n' > .env; chmod 600 .env; run "$EVNX" doctor; expect 1 "FIXED I-161 (DEC-D7): three bad lines are an error, exit 1"; run "$EVNX" doctor --strict; expect 1 "...and with --strict"; printf 'export A=1\nP="-----BEGIN\nMIIE\n-----END"\nB=2\n' > .env; run "$EVNX" doctor; expect 0 "export prefix and multi-line value are valid (parser agreement)"; printf 'P="never closed\nB=2\n' > .env; run "$EVNX" doctor; expect 1 "FIXED I-161 (DEC-D7): an unterminated quote is an error"; printf 'MY-KEY=1\n' > .env; run "$EVNX" doctor; expect 1 "dashed key: invalid for doctor and for the parser (consistent), an error since R-doctor"; }
# R-doctor-EDIT (2026-10-22): DR8 flipped on purpose (I-162, I-163, DEC-D8, DEC-D9, DEC-D17).
DR8() { scene DR8; mkdir empty && cd empty; run "$EVNX" doctor; expect 2 "FIXED I-162 (DEC-D8): an empty directory is exit 2, nothing to diagnose"; cd ..; mkdir tpl && cd tpl && repo && printf 'A=\n' > .env.example && commit t; run "$EVNX" doctor; expect 1 "FIXED I-162 (DEC-D8): template but no .env is an error, exit 1"; run "$EVNX" doctor --strict; expect 1 "...and with --strict"; run "$EVNX" doctor --skip-without-env; expect 0 "DEC-D17: --skip-without-env passes a fresh clone and says it skipped (the pre-commit hook)"; cd ..; mkdir broken && cd broken && printf 'A=1\n' > .env && chmod 600 .env && mkdir requirements.txt; run "$EVNX" doctor; expect 2 "FIXED I-163 (DEC-D9): the check that cannot run is named with its path, the rest finish, exit 2 with No complete verdict"; run "$EVNX" doctor --format json; expect 2 "FIXED I-163: JSON still prints, the check has ran: false"; }
# U0-EDIT (2026-10-14): DR9 -q check rewritten: 0.10.1 made -q hide the banner; the residual is still locked.
# U1-EDIT (2026-10-14): DR9 -q check flipped on purpose: a healthy project prints nothing under -q (I-164).
# U2-EDIT (2026-10-15): DR9 flipped on purpose (I-167 notice; the scene commits .env, so it is tracked).
DR9() { scene DR9; healthy; "$EVNX" -q doctor > q.out 2>&1; "$EVNX" doctor > n.out 2>&1; check '[ ! -s q.out ] && [ -s n.out ]' "I-164 fixed: -q doctor on a healthy project prints nothing; the report still prints when there is a finding"; run env EVNX_OUTPUT_JSON=1 "$EVNX" doctor; expect 0 "EVNX_OUTPUT_JSON=1 gives JSON"; "$EVNX" doctor --format pretty > p.out 2>/dev/null; EVNX_OUTPUT_JSON=1 "$EVNX" doctor --format pretty > p2.out 2>/dev/null; check 'cmp -s p.out p2.out' "explicit --format pretty beats EVNX_OUTPUT_JSON"; run "$EVNX" doctor --format text; expect 0 "hidden alias --format text is accepted (decided: stays)"; printf 'AWS=1\n' > .env; chmod 644 .env; rm .gitignore; commit x; run env EVNX_AUTO_FIX=1 "$EVNX" doctor; expect 1 "I-167 fixed: the mode repair prints a Fixed: notice on stderr; exit 1 because this scene committed .env (tracked, I-157)"; check '[ "$(mode .env)" = 600 ]' "the file was changed"; }
# U8-EDIT (2026-10-17): DR10 flipped — I-175 fixed; a Pipfile or poetry.lock project gets a verdict.
DR10() { scene DR10; repo; printf 'A=1\n' > .env; chmod 600 .env; good_ignore; commit i; for f in "pyproject.toml:[tool.poetry]" "Pipfile:x" "requirements.txt:flask" "package.json:{}" "Cargo.toml:[package]" "go.mod:module x" "composer.json:{}"; do rm -f poetry.lock pyproject.toml Pipfile requirements.txt package.json Cargo.toml go.mod composer.json; printf '%s\n' "${f#*:}" > "${f%%:*}"; printf '%-18s -> ' "${f%%:*}"; "$EVNX" doctor --verbose 2>&1 | grep -iE "detected|^Error" | head -1; done; echo "FIXED I-175 (U8d): the Pipfile line above is a detection"; rm -f pyproject.toml Pipfile requirements.txt package.json Cargo.toml go.mod composer.json; printf '[packages]\nflask="*"\n' > Pipfile; run "$EVNX" doctor; expect 0 "FIXED I-175 (U8d): a Pipfile-only project gets a verdict, not an abort"; rm Pipfile; : > poetry.lock; run "$EVNX" doctor; expect 0 "FIXED I-175 (U8d): a poetry.lock-only project gets a verdict too"; rm poetry.lock; rm -f Pipfile requirements.txt package.json Cargo.toml go.mod composer.json pyproject.toml; printf 'flask\n' > requirements.txt; printf '{}\n' > package.json; run "$EVNX" doctor --verbose; check '"$EVNX" doctor --verbose 2>&1 | grep -q "Detected Python" && "$EVNX" doctor --verbose 2>&1 | grep -q "Detected Node.js"' "FIXED RM-23: every detected type is reported"; rm requirements.txt package.json; printf 'FROM scratch\nCOPY . .\n' > Dockerfile; run "$EVNX" doctor; expect 0 "FIXED S-D5 (RM-22): Dockerfile with no .dockerignore is a warning"
  check '"$EVNX" doctor 2>&1 | grep -q "Dockerfile with no .dockerignore"' "FIXED RM-22: missing .dockerignore is named"
  printf 'node_modules\n' > .dockerignore; run "$EVNX" doctor; expect 0 "RM-22: a .dockerignore without .env* is a warning"
  check '"$EVNX" doctor 2>&1 | grep -q ".dockerignore does not exclude .env"' "RM-22: incomplete .dockerignore is named"
  run "$EVNX" doctor --fix; expect 0 "RM-22: --fix adds .env* to .dockerignore"; run cat .dockerignore
  check 'cp .dockerignore before && "$EVNX" doctor --fix >/dev/null 2>&1; cmp -s before .dockerignore' "RM-22: a second --fix changes nothing"
  check '! "$EVNX" doctor 2>&1 | grep -q "dockerignore"' "RM-22: a correct .dockerignore is not warned about"; }

if [ $# -eq 0 ]; then set -- DR0 DR1 DR2 DR3 DR4 DR5 DR6 DR7 DR8 DR9 DR10; fi
for s in "$@"; do "$s"; done
echo; echo "================ summary: $pass ok, $fail mismatch  (scratch: $DEMO_ROOT) ================"
[ "$fail" -eq 0 ]
